// One MCP-over-HTTP response body → the JSON-RPC envelope.
// StreamableHTTP answers a POST with an SSE frame ("event: message\ndata: {…}")
// unless the server enables JSON responses, so handle both shapes.
function parseRpc(body, what) {
  const text = typeof body === 'string' ? body : JSON.stringify(body ?? '');
  const trimmed = text.trim();
  if (trimmed.startsWith('{')) return JSON.parse(trimmed);
  const frames = trimmed
    .split('\n')
    .filter((line) => line.startsWith('data:'))
    .map((line) => line.slice(5).trim())
    .filter((line) => line.length > 0);
  if (frames.length === 0) {
    throw new Error(what + ': no JSON-RPC payload in MCP response — ' + trimmed.slice(0, 300));
  }
  return JSON.parse(frames[frames.length - 1]);
}

// The initialize response carries the session id in a header; every later
// request on this session must echo it back.
const init = $('Open MCP session').first().json;
if (init.statusCode >= 400) {
  throw new Error('MCP initialize failed with HTTP ' + init.statusCode + ' — ' + String(init.body).slice(0, 300));
}
const envelope = parseRpc(init.body, 'initialize');
if (envelope.error) {
  throw new Error('MCP initialize rejected: ' + envelope.error.code + ' ' + envelope.error.message);
}
const sessionId = (init.headers || {})['mcp-session-id'];
if (!sessionId) {
  throw new Error('MCP initialize returned no mcp-session-id header — is MCP_TRANSPORT=http on the target instance?');
}

// One request per incoming call item. Ids only have to be unique within the
// session; 1 belongs to initialize.
const calls = $('When called by another workflow').all();
return calls.map((item, index) => {
  const tool = item.json.tool;
  const label = item.json.label || tool;
  if (!tool) throw new Error('call #' + index + ' has no \'tool\' field');
  let args;
  try {
    args = item.json.argsJson ? JSON.parse(item.json.argsJson) : {};
  } catch (err) {
    throw new Error('call #' + index + ' (' + tool + '): argsJson is not valid JSON — ' + err.message);
  }
  return {
    json: {
      label,
      tool,
      sessionId,
      rpcBody: {
        jsonrpc: '2.0',
        id: index + 2,
        method: 'tools/call',
        params: { name: tool, arguments: args },
      },
    },
  };
});

// One MCP-over-HTTP response body → the JSON-RPC envelope.
// StreamableHTTP answers a POST with an SSE frame ("event: message\ndata: {…}")
// unless the server enables JSON responses, so handle both shapes.
function parseRpc(body, what) {
  const text = typeof body === 'string' ? body : JSON.stringify(body ?? '');
  const trimmed = text.trim();
  if (trimmed.startsWith('{')) return JSON.parse(trimmed);
  const frames = trimmed
    .split('\n')
    .filter((line) => line.startsWith('data:'))
    .map((line) => line.slice(5).trim())
    .filter((line) => line.length > 0);
  if (frames.length === 0) {
    throw new Error(what + ': no JSON-RPC payload in MCP response — ' + trimmed.slice(0, 300));
  }
  return JSON.parse(frames[frames.length - 1]);
}

// Zip the tools/call responses back onto the call specs by position: the HTTP
// node replaced the items with its own output, so the label lives next door.
const calls = $('Build one request per call').all();
const responses = $input.all();

return responses.map((response, index) => {
  const call = calls[index] ? calls[index].json : {};
  const tool = call.tool || 'unknown-tool';
  const label = call.label || tool;
  const status = response.json.statusCode;
  if (status >= 400) {
    throw new Error(label + ' (' + tool + '): HTTP ' + status + ' — ' + String(response.json.body).slice(0, 300));
  }
  const envelope = parseRpc(response.json.body, label);
  if (envelope.error) {
    throw new Error(label + ' (' + tool + '): JSON-RPC ' + envelope.error.code + ' ' + envelope.error.message);
  }
  const result = envelope.result || {};
  const text = (result.content || [])
    .filter((part) => part.type === 'text')
    .map((part) => part.text)
    .join('\n');
  // MCP reports a tool-level failure in-band: isError with the message as text.
  if (result.isError) {
    throw new Error(label + ' (' + tool + ') failed: ' + text.slice(0, 500));
  }
  // Our tools answer with pretty JSON in one text part (see packages/mcp/src/result.ts).
  // Anything that is not JSON stays a string — same lenient rule the agent's
  // workflow executor uses when it binds a tool result.
  let payload = text;
  if (result.structuredContent !== undefined) {
    payload = result.structuredContent;
  } else {
    try {
      payload = JSON.parse(text);
    } catch {
      payload = text;
    }
  }
  return { json: { label, tool, result: payload } };
});

// The DELETE above replaced the items with its own response; hand the
// caller back the parsed tool results instead.
return $('Parse the responses').all();
